@IsTest private class Observation62 {
@IsTest static void trace(){
System.assert(false,'OBS|'+FrameSample.observe());
}
@IsTest static void object(){
SparseSample__c sample=new SparseSample__c(Name='sample');insert sample;SparseSample__c row=[SELECT Name FROM SparseSample__c WHERE Id=:sample.Id];List<String> keys=new List<String>(SparseSample__c.SObjectType.getDescribe().fields.getMap().keySet());keys.sort();System.assert(false,'OBS|'+JSON.serialize(new List<Object>{String.valueOf(row).replace(String.valueOf(row.Id),'[RECORD_ID]'),keys}));
}
@IsTest static void snapshot(){
Account sample=new Account(Name='before');Map<String,Object> fields=sample.getPopulatedFieldsAsMap();sample.Name='after';System.assert(false,'OBS|'+JSON.serialize(new List<Object>{fields.get('Name'),sample.Name}));
}
@IsTest static void mutation(){
Account sample=new Account(Name='before');Map<String,Object> fields=sample.getPopulatedFieldsAsMap();try{fields.put('Name','after');System.assert(false,'OBS|mutation allowed');}catch(Exception e){System.assert(false,'OBS|caught '+e.getTypeName()+': '+e.getMessage());}
}
}

